{"path": "zipper.py", "content": "class Zipper:
    """Zipper over binary trees represented as dicts with keys
    'value', 'left' and 'right' (children are dicts or None)."""

    def __init__(self, value, left, right, path):
        self._value = value
        self._left = left
        self._right = right
        # path: tuple of (direction, parent_value, other_subtree)
        self._path = path

    @staticmethod
    def from_tree(tree):
        if tree is None:
            return None
        return Zipper(tree["value"], tree["left"], tree["right"], ())

    def _node(self):
        return {"value": self._value, "left": self._left, "right": self._right}

    def value(self):
        return self._value

    def set_value(self, value):
        return Zipper(value, self._left, self._right, self._path)

    def left(self):
        if self._left is None:
            return None
        t = self._left
        return Zipper(t["value"], t["left"], t["right"],
                      (("left", self._value, self._right),) + self._path)

    def set_left(self, tree):
        return Zipper(self._value, tree, self._right, self._path)

    def right(self):
        if self._right is None:
            return None
        t = self._right
        return Zipper(t["value"], t["left"], t["right"],
                      (("right", self._value, self._left),) + self._path)

    def set_right(self, tree):
        return Zipper(self._value, self._left, tree, self._path)

    def up(self):
        if not self._path:
            return None
        (direction, pvalue, other), rest = self._path[0], self._path[1:]
        node = self._node()
        if direction == "left":
            return Zipper(pvalue, node, other, rest)
        return Zipper(pvalue, other, node, rest)

    def to_tree(self):
        z = self
        while z._path:
            z = z.up()
        return z._node()

    def __eq__(self, other):
        return (isinstance(other, Zipper)
                and self._node() == other._node()
                and self._path == other._path)
"}
